-- M1 第二块 PR2：默认模型、价格表、用量记录、系统设置（主密钥备份确认）。
-- Modify "models" table
ALTER TABLE "models" ADD COLUMN "is_default" boolean NOT NULL DEFAULT false, ADD COLUMN "price_input_micros" bigint NOT NULL DEFAULT 0, ADD COLUMN "price_cached_micros" bigint NOT NULL DEFAULT 0, ADD COLUMN "price_output_micros" bigint NOT NULL DEFAULT 0, ADD COLUMN "currency" character varying NOT NULL DEFAULT 'CNY';
-- Create "system_settings" table
CREATE TABLE "system_settings" ("id" bigint NOT NULL GENERATED BY DEFAULT AS IDENTITY, "key" character varying NOT NULL, "value" jsonb NOT NULL, "updated_by" bigint NULL, "updated_at" timestamptz NOT NULL, PRIMARY KEY ("id"));
-- Create index "system_settings_key_key" to table: "system_settings"
CREATE UNIQUE INDEX "system_settings_key_key" ON "system_settings" ("key");
-- Create "usage_records" table
CREATE TABLE "usage_records" ("id" bigint NOT NULL GENERATED BY DEFAULT AS IDENTITY, "org_id" bigint NOT NULL, "user_id" bigint NOT NULL, "department_id" bigint NULL, "model_id" bigint NOT NULL, "model_name" character varying NOT NULL, "provider_id" bigint NOT NULL, "request_id" character varying NOT NULL DEFAULT '', "purpose" character varying NOT NULL DEFAULT 'chat', "stream" boolean NOT NULL DEFAULT false, "status" character varying NOT NULL DEFAULT 'ok', "error_code" character varying NOT NULL DEFAULT '', "prompt_tokens" bigint NOT NULL DEFAULT 0, "cached_tokens" bigint NOT NULL DEFAULT 0, "completion_tokens" bigint NOT NULL DEFAULT 0, "reasoning_tokens" bigint NOT NULL DEFAULT 0, "total_tokens" bigint NOT NULL DEFAULT 0, "cost_micros" bigint NOT NULL DEFAULT 0, "currency" character varying NOT NULL DEFAULT 'CNY', "estimated" boolean NOT NULL DEFAULT false, "latency_ms" bigint NOT NULL DEFAULT 0, "created_at" timestamptz NOT NULL, PRIMARY KEY ("id"));
-- Create index "usagerecord_org_id_created_at" to table: "usage_records"
CREATE INDEX "usagerecord_org_id_created_at" ON "usage_records" ("org_id", "created_at");
-- Create index "usagerecord_user_id_created_at" to table: "usage_records"
CREATE INDEX "usagerecord_user_id_created_at" ON "usage_records" ("user_id", "created_at");
-- Create index "usagerecord_department_id_created_at" to table: "usage_records"
CREATE INDEX "usagerecord_department_id_created_at" ON "usage_records" ("department_id", "created_at");
-- Create index "usagerecord_model_id_created_at" to table: "usage_records"
CREATE INDEX "usagerecord_model_id_created_at" ON "usage_records" ("model_id", "created_at");
-- 模型 ACL 的 resource_id 由模型名改为模型 ID（改名不再丢授权）。
UPDATE "acl" SET "resource_id" = m."id"::text FROM "models" m WHERE "acl"."resource_type" = 'model' AND "acl"."resource_id" = m."name";
